(() => {
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='atlas-grain-adventure-v1';
const steps=['Mirar fuentes','Ubicar en el tiempo','Organizar la comunidad','Contrastar ideas','Mi explicación'];
const events=[['urban','c. 3400–3000 a. C.','Ciudades en el sur de Mesopotamia','Uruk y otros asentamientos crecen; aparecen registros escritos. Ciudad y escritura son procesos relacionados, no fechas únicas.'],['granary','c. 1981–1975 a. C.','Un granero representado en Egipto','El modelo funerario de Meketre permite investigar tareas. Es posterior a las primeras ciudades mesopotámicas y pertenece a otra región.'],['receipt','c. 517 a. C.','Un recibo mesopotámico','La tablilla conservada por el Met registra dátiles. No es una muestra de los primeros escritos.']];
const roles=[['grow','Cultivo'],['store','Almacenamiento'],['craft','Oficios'],['record','Registros']];
const questions=[['¿Qué relación está mejor apoyada por las fuentes?',['El alimento, los oficios y los registros pueden relacionarse con la organización de una comunidad.','Cultivar convierte automáticamente cualquier aldea en ciudad.','La tablilla de 517 a. C. es la primera escritura conocida.'],0,'Los objetos permiten investigar tareas y registros; el contexto de Uruk ayuda a relacionarlos con la vida urbana. Ningún objeto demuestra una causa única.'],['¿Qué falta para conocer quién recibía el alimento?',['Nada: basta con contar figuras en el modelo.','Otros registros, contexto arqueológico y voces que estas fuentes no conservan.','El resultado numérico del juego.'],1,'Las fuentes tienen límites. La fotografía de un modelo funerario y un recibo no describen toda una sociedad. El juego tampoco es evidencia histórica.']];
const fresh=()=>({version:1,step:0,depth:'explorar',done:[false,false,false,false,false],notes:{detail:'',question:'',reason:'',claim:'',evidence:'',limit:''},order:[],timeline:false,alloc:{grow:4,store:3,craft:3,record:2},weather:'normal',ran:false,answers:[null,null],complete:false});
let state=fresh(),persistent=true;
function restore(){try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(!raw||raw.version!==1)return;state=fresh();if(Number.isInteger(raw.step)&&raw.step>=0&&raw.step<5)state.step=raw.step;if(['explorar','comprender','profundizar'].includes(raw.depth))state.depth=raw.depth;for(const k of Object.keys(state.notes))if(typeof raw.notes?.[k]==='string')state.notes[k]=raw.notes[k].slice(0,5000);if(Array.isArray(raw.order)&&new Set(raw.order).size===raw.order.length&&raw.order.every(id=>events.some(e=>e[0]===id)))state.order=raw.order;for(const [k]of roles)if(Number.isInteger(raw.alloc?.[k])&&raw.alloc[k]>=0&&raw.alloc[k]<=12)state.alloc[k]=raw.alloc[k];if(Object.values(state.alloc).reduce((a,b)=>a+b,0)>12)state.alloc=fresh().alloc;state.weather=raw.weather==='dry'?'dry':'normal';state.timeline=raw.timeline===true&&state.order.join(',')==='urban,granary,receipt';state.ran=raw.ran===true&&Object.values(state.alloc).reduce((a,b)=>a+b,0)===12;if(Array.isArray(raw.answers))state.answers=questions.map((q,i)=>Number.isInteger(raw.answers[i])&&raw.answers[i]>=0&&raw.answers[i]<3?raw.answers[i]:null);state.done=[raw.done?.[0]===true&&!!state.notes.detail.trim(),state.timeline,state.ran,state.answers.every(x=>x!==null),false];state.complete=raw.complete===true&&state.done.slice(0,4).every(Boolean)&&['claim','evidence','limit'].every(k=>state.notes[k].trim());state.done[4]=state.complete;}catch{persistent=false;}}
function save(){if(!state.done.slice(0,4).every(Boolean)){state.complete=false;state.done[4]=false;}try{localStorage.setItem(key,JSON.stringify(state));persistent=true;}catch{persistent=false;}const progress=$('#gaProgress');if(progress)progress.textContent=state.done.filter(Boolean).length+' de 5 etapas realizadas';const el=$('#gaSave');if(el)el.textContent=persistent?'Progreso guardado en este dispositivo.':'El guardado no está disponible. Tu avance se mantiene mientras esta página esté abierta.';}
const note=(id,label)=>`<label for="ga-${id}">${label}</label><textarea id="ga-${id}" data-ga-note="${id}" rows="3" maxlength="5000">${esc(state.notes[id])}</textarea>`;
function sourceStage(){return `<h2>¿Cómo se coordinan el alimento y el trabajo?</h2><p>Compara dos objetos de épocas y lugares distintos. Primero describe un detalle visible; después consulta las fichas.</p><div class="ga-sources"><figure><img src="assets/source-granary.webp" alt="Fotografía del modelo funerario de un granero con figuras y escribas"><figcaption>Egipto · c. 1981–1975 a. C. · Met, 20.3.11. Modelo funerario de la tumba de Meketre.</figcaption><a href="https://www.metmuseum.org/art/collection/search/545281" target="_blank" rel="noopener">Consultar objeto y ficha</a></figure><figure><img src="assets/source-tablet.webp" alt="Fotografía de una tablilla de arcilla con signos cuneiformes"><figcaption>Mesopotamia, probablemente Borsippa · c. 517 a. C. · Met, 86.11.403. Recibo de dátiles según el catálogo.</figcaption><a href="https://www.metmuseum.org/art/collection/search/322021" target="_blank" rel="noopener">Consultar objeto y ficha</a></figure></div><p class="ga-caption">Fotografías actuales de objetos antiguos: Met Open Access, dominio público. No son fotografías de su época. La tablilla no se traduce aquí.</p><a href="#vida-cotidiana">Abrir el laboratorio para ampliar las fotografías</a>${note('detail',state.depth==='explorar'?'Señala o describe un detalle que ves':state.depth==='comprender'?'Compara una tarea visible con un dato de la ficha':'Distingue observación y catálogo; considera contexto funerario y procedencia probable')}${note('question','¿Qué pregunta no puedes responder con estas fuentes?')}<button id="gaObserve" class="atlas-button">Registrar mi observación</button><p id="gaObserveFeedback" role="status">${state.done[0]?'Observación registrada. Puedes seguir investigando.':''}</p>`;}
function timeStage(){return `<h2>Ordena las referencias: de más antigua a más reciente</h2><p>En las fechas a. C., un número mayor suele indicar un momento más antiguo. Los intervalos son aproximados. Esta comparación une regiones distintas; no describe una sola cadena de causas.</p><div class="ga-pool">${[2,0,1].map(i=>events[i]).filter(e=>!state.order.includes(e[0])).map(e=>`<button data-ga-event="${e[0]}"><strong>${e[1]}</strong><span>${e[2]}</span></button>`).join('')}</div><ol class="ga-timeline">${state.order.map(id=>{const e=events.find(e=>e[0]===id);return `<li><strong>${e[1]} · ${e[2]}</strong><p>${e[3]}</p></li>`;}).join('')}</ol><div class="ga-actions"><button id="gaUndo" class="atlas-outline" ${state.order.length?'':'disabled'}>Quitar la última</button><button id="gaCheckTime" class="atlas-button" ${state.order.length===3?'':'disabled'}>Comprobar orden</button></div><p id="gaTimeFeedback" role="status">${state.timeline?'Orden correcto. Un objeto posterior no prueba el origen de un proceso anterior.':''}</p><details><summary>Fuentes para la primera referencia</summary><a href="https://www.getty.edu/news/getty-presents-mesopotamia-civilization-begins/" target="_blank" rel="noopener">Getty · primeras ciudades</a><br><a href="https://www.metmuseum.org/es/essays/the-origins-of-writing" target="_blank" rel="noopener">Met · orígenes de la escritura</a></details>`;}
function outcome(){const a=state.alloc,yieldRate=state.weather==='dry'?2:3,food=a.grow*yieldRate,capacity=a.store*4,usable=Math.min(food,capacity),balance=usable-10;return {food,capacity,usable,balance};}
function results(){const r=outcome();return `<div class="ga-results"><h3>Resultado del modelo</h3><p>${state.weather==='dry'?'Mala cosecha: cada unidad de cultivo produce 2.':'Cosecha normal: cada unidad de cultivo produce 3.'} Almacenamiento conserva hasta 4 por unidad. Necesidad común: 10.</p>${[['Producción',r.food],['Capacidad de conservación',r.capacity],['Alimento utilizable',r.usable]].map(([l,v])=>`<div class="ga-bar"><span>${l}: <strong>${v}</strong></span><meter min="0" max="48" value="${v}" aria-label="${l}">${v}</meter></div>`).join('')}<p><strong>${r.balance>=0?`Reserva de ${r.balance} unidades.`:`Faltan ${-r.balance} unidades para cubrir la necesidad.`}</strong> ${state.alloc.craft>=2?'Hay dedicación a oficios.':'Los oficios reciben poca dedicación.'} ${state.alloc.record>=2?'Hay dedicación a registros.':'El registro recibe poca dedicación.'}</p><p>Las reglas y unidades son inventadas para comparar decisiones. No estiman cosechas reales ni miden el bienestar histórico. No hay una asignación que explique por sí sola el nacimiento de una ciudad.</p></div>`;}
function buildStage(){return `<h2>Construye un plan de trabajo</h2><p>Reparte 12 unidades de trabajo. Restar a un área libera unidades para otra. Prueba un plan, cambia la cosecha y observa qué sacrificas.</p><p class="ga-budget">Sin asignar: <strong id="gaRemaining">${12-Object.values(state.alloc).reduce((a,b)=>a+b,0)}</strong> de 12</p><div class="ga-roles">${roles.map(([id,l])=>`<article><h3>${l}</h3><div><button data-ga-adjust="${id}" data-delta="-1" aria-label="Restar trabajo a ${l}">−</button><output>${state.alloc[id]}</output><button data-ga-adjust="${id}" data-delta="1" aria-label="Añadir trabajo a ${l}">+</button></div><p>${{grow:'Produce alimento.',store:'Conserva parte de lo producido.',craft:'Representa tareas especializadas.',record:'Representa contabilidad y coordinación.'}[id]}</p></article>`).join('')}</div><label for="gaWeather">Condiciones de cosecha</label><select id="gaWeather"><option value="normal" ${state.weather==='normal'?'selected':''}>Normal</option><option value="dry" ${state.weather==='dry'?'selected':''}>Mala cosecha</option></select><button id="gaRun" class="atlas-button" ${Object.values(state.alloc).reduce((a,b)=>a+b,0)===12?'':'disabled'}>Probar mi plan</button><div id="gaResult" role="status">${state.ran?results():''}</div>${note('reason',state.depth==='explorar'?'¿Qué cambiaste y qué ocurrió?':state.depth==='comprender'?'Compara dos planes: ¿qué ganas y qué sacrificas?':'Explica un supuesto del modelo y una variable ausente: poder, distribución, ambiente o intercambio')}`;}
function ideaStage(){return `<h2>Decide qué podemos sostener</h2><p>Elige una respuesta y revisa la explicación. Una decisión del juego no equivale a una prueba del pasado.</p>${questions.map((q,i)=>`<article class="ga-question"><h3>${q[0]}</h3><div>${q[1].map((o,j)=>`<button data-ga-answer="${i}" data-option="${j}" ${state.answers[i]!==null?'disabled':''} class="${state.answers[i]!==null&&j===q[2]?'ga-correct':''}">${o}</button>`).join('')}</div><p id="gaFeedback${i}" role="status">${state.answers[i]!==null?`${state.answers[i]===q[2]?'Respuesta apoyada.':'Revisa la opción señalada.'} ${q[3]}`:''}</p></article>`).join('')}`;}
function finishStage(){return `<h2>Explica con evidencia y reconoce un límite</h2><p>${state.depth==='explorar'?'Puedes conversar o dibujar primero y escribir una frase en cada espacio.':state.depth==='comprender'?'Conecta dos fuentes y revisa la diferencia entre causa, relación y coincidencia.':'Formula una explicación con varias causas. Evalúa la independencia de las fuentes y las voces ausentes.'}</p>${note('claim','Mi explicación: ¿cómo se relacionan alimento, trabajo y registros?')}${note('evidence','Mi evidencia: nombra un objeto o una fuente y un detalle que apoye tu explicación')}${note('limit','Mi límite: ¿qué no sabemos todavía y con qué otra fuente lo investigarías?')}<button id="gaFinish" class="atlas-button">Completar la aventura</button><p id="gaFinishFeedback" role="status">${state.complete?'Aventura completada. Conserva tu explicación y vuelve a revisarla cuando encuentres otra fuente.':''}</p><details class="ga-summary"><summary>Mi recorrido y las fuentes consultadas</summary><p>Observación: ${esc(state.notes.detail)}</p><p>Pregunta: ${esc(state.notes.question)}</p><p>Orden elegido: ${state.order.map(id=>esc(events.find(e=>e[0]===id)[1])).join(' · ')}</p><p>Plan: ${roles.map(([id,l])=>`${l}: ${state.alloc[id]}`).join(' · ')}. Cosecha: ${state.weather==='dry'?'mala':'normal'}.</p><p>Justificación: ${esc(state.notes.reason)}</p><p>Fuentes: <a href="https://www.metmuseum.org/art/collection/search/545281">Met · granero de Meketre</a>; <a href="https://www.metmuseum.org/art/collection/search/322021">Met · recibo de dátiles</a>; <a href="https://www.getty.edu/news/getty-presents-mesopotamia-civilization-begins/">Getty · primeras ciudades</a>; <a href="https://www.metmuseum.org/es/essays/the-origins-of-writing">Met · escritura</a>.</p></details><button id="gaPrint" class="atlas-outline">Imprimir mi investigación</button><p>Tu texto no recibe una calificación automática. Comenta la relación entre tu afirmación y la evidencia con otra persona.</p><a href="#ruta/antigua">Continuar en Historia antigua</a>`;}
function render(){const host=$('#grainAdventure');if(!host)return;host.innerHTML=`<header class="ga-top"><div><p class="eyebrow">AVENTURA · 25–40 MIN</p><h1>Del grano a las ciudades</h1></div><button id="gaProject" class="atlas-outline">Proyectar</button></header><div class="ga-toolbar"><label for="gaDepth">Profundidad</label><select id="gaDepth">${[['explorar','Explorar'],['comprender','Comprender'],['profundizar','Profundizar']].map(([id,l])=>`<option value="${id}" ${state.depth===id?'selected':''}>${l}</option>`).join('')}</select><span id="gaProgress">${state.done.filter(Boolean).length} de 5 etapas realizadas</span><button id="gaReset" class="atlas-outline">Reiniciar aventura</button></div><nav class="ga-steps" aria-label="Etapas de la aventura">${steps.map((l,i)=>`<button data-ga-step="${i}" aria-current="${state.step===i?'step':'false'}">${i+1}. ${l}${state.done[i]?' · Realizada':''}</button>`).join('')}</nav><p id="gaSave" class="ga-caption">${persistent?'Progreso guardado en este dispositivo.':'El guardado no está disponible. Tu avance se mantiene mientras esta página esté abierta.'}</p><div class="ga-stage">${[sourceStage,timeStage,buildStage,ideaStage,finishStage][state.step]()}</div><div class="ga-actions ga-navigation"><button id="gaPrev" class="atlas-outline" ${state.step===0?'disabled':''}>Etapa anterior</button><button id="gaNext" class="atlas-button" ${state.step===4?'disabled':''}>Siguiente etapa</button></div>`;bind();}
function changeStep(i){state.step=i;save();render();$('.ga-stage h2')?.setAttribute('tabindex','-1');$('.ga-stage h2')?.focus();}
function bind(){
 $('#gaDepth').onchange=e=>{state.depth=e.target.value;save();render();};$('#gaProject').onclick=()=>$('#projectorBtn').click();$('#gaReset').onclick=()=>{state=fresh();save();render();};$$('[data-ga-step]').forEach(b=>b.onclick=()=>changeStep(+b.dataset.gaStep));$('#gaPrev').onclick=()=>{if(state.step>0)changeStep(state.step-1);};$('#gaNext').onclick=()=>{if(state.step<4)changeStep(state.step+1);};
 $$('[data-ga-note]').forEach(n=>n.oninput=()=>{state.notes[n.dataset.gaNote]=n.value;if(n.dataset.gaNote==='detail')state.done[0]=false;state.complete=false;state.done[4]=false;save();});
 if($('#gaObserve'))$('#gaObserve').onclick=()=>{state.done[0]=!!state.notes.detail.trim();save();$('#gaObserveFeedback').textContent=state.done[0]?'Observación registrada. Puedes seguir investigando.':'Escribe un detalle visible o un dato identificado en la ficha.';};
 $$('[data-ga-event]').forEach(b=>b.onclick=()=>{state.order.push(b.dataset.gaEvent);state.timeline=false;state.done[1]=false;save();render();});if($('#gaUndo'))$('#gaUndo').onclick=()=>{state.order.pop();state.timeline=false;state.done[1]=false;save();render();};if($('#gaCheckTime'))$('#gaCheckTime').onclick=()=>{state.timeline=state.order.join(',')==='urban,granary,receipt';state.done[1]=state.timeline;save();$('#gaTimeFeedback').textContent=state.timeline?'Orden correcto. El granero y el recibo son posteriores a la referencia urbana.':'Revisa las fechas a. C.: 3400–3000 es anterior a 1981–1975, y ambos son anteriores a 517. Puedes quitar la última tarjeta para corregir.';};
 $$('[data-ga-adjust]').forEach(b=>b.onclick=()=>{const id=b.dataset.gaAdjust,d=+b.dataset.delta,total=Object.values(state.alloc).reduce((a,b)=>a+b,0);if(d<0&&state.alloc[id]===0||d>0&&total>=12)return;state.alloc[id]+=d;state.ran=false;state.done[2]=false;save();render();});if($('#gaWeather'))$('#gaWeather').onchange=e=>{state.weather=e.target.value;state.ran=false;state.done[2]=false;save();render();};if($('#gaRun'))$('#gaRun').onclick=()=>{if(Object.values(state.alloc).reduce((a,b)=>a+b,0)!==12)return;state.ran=true;state.done[2]=true;save();render();};
 $$('[data-ga-answer]').forEach(b=>b.onclick=()=>{const i=+b.dataset.gaAnswer;if(state.answers[i]!==null)return;state.answers[i]=+b.dataset.option;state.done[3]=state.answers.every(x=>x!==null);save();render();});
 if($('#gaFinish'))$('#gaFinish').onclick=()=>{if(!['claim','evidence','limit'].every(k=>state.notes[k].trim())){$('#gaFinishFeedback').textContent='Completa la explicación, la evidencia y el límite antes de terminar.';return;}if(!state.done.slice(0,4).every(Boolean)){$('#gaFinishFeedback').textContent='Revisa las etapas pendientes: registra un detalle, comprueba la cronología, prueba un plan y responde las dos preguntas.';return;}state.complete=true;state.done[4]=true;save();render();};if($('#gaPrint'))$('#gaPrint').onclick=()=>{$('.ga-summary').open=true;window.print();};
}
restore();render();window.AtlasGrainAdventure={reload:()=>{state=fresh();persistent=true;restore();render();}};
})();
